// Terse adapter: the only place the bridge touches the CaseActor. Thin by
// design; every method maps 1:1 onto an actor method generated by
// `terse actor generate`. Configuration follows the generated client:
// TERSE_ACTOR_URL (default local dev server) and TERSE_API_KEY (hosted only).

export async function createTerse({ actorUrl, apiKey } = {}) {
  if (actorUrl) process.env.TERSE_ACTOR_URL = actorUrl;
  if (apiKey) process.env.TERSE_API_KEY = apiKey;
  // Import after the environment is set so the generated runtime picks it up.
  const { actors } = await import("../generated/index.js");
  const actor = (caseId) => actors.CaseActor.get(caseId);
  return {
    openCase: (caseId, registry, phase, head) => actor(caseId).openCase(registry, phase, head),
    appendEntry: (caseId, entry, head) => actor(caseId).appendEntry(entry, head),
    closePhase: (caseId, entry, head, next) => actor(caseId).closePhase(entry, head, next),
    getPhase: (caseId) => actor(caseId).getPhase(),
    getRegistry: (caseId) => actor(caseId).getRegistry(),
    getHead: (caseId) => actor(caseId).getHead(),
    getSummary: (caseId) => actor(caseId).getSummary(),
    getTranscript: (caseId, fromSeq = 0) => actor(caseId).getTranscript(fromSeq),
    setCertificate: (caseId, bundle) => actor(caseId).setCertificate(bundle),
    getCertificate: (caseId) => actor(caseId).getCertificate(),
    close: async () => {},
  };
}
